226	/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
227	export const currentUser = cache(async (): Promise<User | null> => {
228	  const real = await realUser();
229	  if (!real) return null;
230	  if (real.role === "ADMIN") {
231	    const jar = await cookies();
232	    const imp = jar.get(IMP_COOKIE)?.value;
233	    if (imp) {
234	      try {
235	        const { payload } = await jwtVerify(imp, secret);
236	        if (payload.typ === "imp" && payload.adminId === real.id && typeof payload.sub === "string") {
237	          const target = await db.user.findUnique({ where: { id: payload.sub } });
238	          // The token outlives the checks `impersonateUser` made when it minted
239	          // it (2h), so they are re-made here against the CURRENT row rather
240	          // than trusted from the past:
241	          //
242	          //  - suspended: `realUser` refuses to hand out a session for a
243	          //    suspended account, and impersonation must not be a side door that
244	          //    resurrects one. Reviewing a suspended abuser's account is a
245	          //    read-only job; it must not come with the ability to act as them.
246	          //  - ADMIN: refused at mint time, but a customer promoted DURING an
247	          //    open impersonation would otherwise turn the impersonator's
248	          //    `currentUser()` into an ADMIN — and `requireAdmin` is built on
249	          //    `currentUser`, so admin actions would run attributed to the
250	          //    promoted account instead of the person taking them. The rule that
251	          //    admins refuse to act while impersonating depends on this.
252	          //
253	          // Falling through to the real admin is the safe failure: they are
254	          // simply themselves again, which is visible on screen.
255	          if (target && !target.suspended && target.role !== "ADMIN") return target;
256	        }
257	      } catch {
258	        /* expired/invalid impersonation — fall through to real user */
259	      }
260	    }
261	  }
262	  return real;
263	});
264	
265	/** Non-null when the current request is an admin impersonating a customer. */
266	export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
267	  const real = await realUser();
268	  if (!real || real.role !== "ADMIN") return null;
269	  const target = await currentUser();
270	  if (!target || target.id === real.id) return null;
271	  return { admin: real, target };
272	});
273	
274	export async function setImpersonation(targetUserId: string) {
275	  const real = await realUser();
276	  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
277	  // `typ: "imp"` marks this as a grant, never a session (see assertSessionToken).
278	  const token = await new SignJWT({ sub: targetUserId, adminId: real.id, typ: "imp" })
279	    .setProtectedHeader({ alg: "HS256" })
280	    .setIssuedAt()
281	    .setExpirationTime("2h")
282	    .sign(secret);
283	  const jar = await cookies();
284	  jar.set(IMP_COOKIE, token, {
285	    httpOnly: true,
286	    sameSite: "lax",
287	    secure: process.env.NODE_ENV === "production",
288	    path: "/",
289	    maxAge: 7200,
290	  });
291	}
292	
293	export async function clearImpersonation() {
294	  const jar = await cookies();
295	  jar.delete(IMP_COOKIE);
296	}
297	
298	/**
299	 * Guard for wallet-debit / paid actions: refuse to run while an admin is
300	 * impersonating a customer. Keeps money movements attributable to the account
301	 * holder and prevents an admin from spending a customer's balance on their behalf.
302	 * Throws a friendly, user-facing error. Call at the top of every spend path.
303	 */
304	export async function assertNotImpersonating(): Promise<void> {
305	  const imp = await impersonating();
306	  if (imp) {
307	    throw new Error(
308	      "This action is disabled while impersonating a customer. Stop impersonating to continue.",
309	    );
310	  }
311	}
