313	export async function requireUser(): Promise<User> {
314	  const user = await currentUser();
315	  if (!user) throw new Error("UNAUTHORIZED");
316	  return user;
317	}
318	
319	export async function requireAdmin(): Promise<User> {
320	  const user = await requireUser();
321	  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
322	  return user;
323	}
324	
325	/**
326	 * Require any staff role (SUPPORT / BILLING / ADMIN). Uses the real signed-in
327	 * account, ignoring impersonation. Throws FORBIDDEN for customers. Fine-grained
328	 * per-area gating lives in lib/rbac.ts (`requireArea`).
329	 */
330	export async function requireStaff(): Promise<User> {
331	  const user = await realUser();
332	  if (!user) throw new Error("UNAUTHORIZED");
333	  if (user.role !== "SUPPORT" && user.role !== "BILLING" && user.role !== "ADMIN") {
334	    throw new Error("FORBIDDEN");
335	  }
336	  return user;
337	}
