19	export default async function AdminUserDetail({ params }: { params: Promise<{ id: string }> }) {
20	  /*
21	   * `clients` is a SUPPORT area (lib/rbac.ts AREA_ROLES), but every write control
22	   * on this page — Credit, Impersonate, Suspend user, Suspend server — is behind
23	   * an action that calls `requireAdmin()`. A SUPPORT agent was therefore shown an
24	   * "Impersonate" button beside every customer, and a "Suspend" button beside
25	   * every server, and got an unhandled FORBIDDEN throw on click: no error state,
26	   * just a blank error boundary.
27	   *
28	   * A control a role cannot use is not a permission, it is a promise the server
29	   * refuses to keep. The RBAC decision stays exactly where it is enforced — inside
30	   * the action — and the page simply stops rendering what it knows will be
31	   * refused. Nothing is granted here; controls are only ever removed.
32	   */
33	  const me = await requireArea("clients");
34	  const canAct = me.role === "ADMIN";
35	  // Messaging a customer directly is the same bar as replying to their
36	  // tickets — any staff member with the supportTickets grant, not ADMIN-only
37	  // like Credit/Impersonate/Suspend above.
38	  const canMessage = await hasAreaAccess(me, "supportTickets");
39	  const { id } = await params;
40	
41	  const [user, renewalPrices, staffDms] = await Promise.all([
42	    db.user.findUnique({
43	      where: { id },
44	      include: {
45	      servers: {
46	        include: {
47	          plan: true,
48	          gamePlan: { select: { name: true, priceCents: true, termMonths: true } },
49	          // Needed by renewalCharge (via serverMonthlyCents) to price that add-on.
50	          dedicatedIp: { select: { id: true } },
51	        },
52	        orderBy: { createdAt: "desc" },
53	      },
54	      // Shared web hosting accounts (HostingAccount) — the second product line the
55	      // profile previously ignored entirely.
56	      hostingAccounts: {
57	        include: {
58	          plan: { select: { name: true, priceCents: true } },
59	          node: { select: { name: true } },
60	        },
61	        orderBy: { createdAt: "desc" },
62	      },
63	      // Business email subscriptions (EmailSubscription) with their mailbox count.
64	      emailSubscriptions: {
65	        include: {
66	          emailPlan: { select: { name: true, priceCents: true, termMonths: true } },
67	          _count: { select: { mailboxes: true } },
68	        },
69	        orderBy: { createdAt: "desc" },
70	      },
71	      transactions: { orderBy: { createdAt: "desc" }, take: 20 },
72	      invoices: { orderBy: { createdAt: "desc" } },
73	      tickets: { orderBy: { updatedAt: "desc" } },
