import bcrypt from "bcryptjs";
import { db } from "./lib/db";

async function main() {
  const pw = await bcrypt.hash("TestPass123!", 12);

  const admin = await db.user.upsert({
    where: { email: "admin@fiximp.local" },
    update: {},
    create: {
      email: "admin@fiximp.local",
      name: "Test Admin",
      passwordHash: pw,
      role: "ADMIN",
      emailVerified: true,
    },
  });

  const customer = await db.user.upsert({
    where: { email: "customer@fiximp.local" },
    update: {},
    create: {
      email: "customer@fiximp.local",
      name: "Test Customer",
      passwordHash: pw,
      role: "CUSTOMER",
      emailVerified: true,
    },
  });

  // A real, older "sign-in" Visit row for the customer, so we can tell it
  // apart from anything an impersonation session writes.
  await db.visit.create({
    data: {
      ip: "203.0.113.50", // TEST-NET-3, Karachi-ish stand-in
      path: "/dashboard",
      kind: "portal",
      userId: customer.id,
      country: "Pakistan",
      city: "Karachi",
      createdAt: new Date(Date.now() - 2 * 24 * 60 * 60 * 1000),
    },
  });

  // A ticket owned by the customer, to test bug 2 against.
  const ticket = await db.ticket.upsert({
    where: { id: "fiximp-test-ticket" },
    update: {},
    create: {
      id: "fiximp-test-ticket",
      subject: "Test ticket for impersonation bug repro",
      userId: customer.id,
      messages: {
        create: {
          body: "This is my original message.",
          authorId: customer.id,
          isStaff: false,
        },
      },
    },
  });

  console.log(JSON.stringify({ adminId: admin.id, customerId: customer.id, ticketId: ticket.id }, null, 2));
  await db.$disconnect();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

