import { chromium } from "playwright";

const BASE_PORTAL = "http://portal.fiximp.local:3099";
const BASE_ADMIN = "http://admin.fiximp.local:3099";

const log = (...a) => console.log(new Date().toISOString().slice(11, 23), ...a);

const browser = await chromium.launch();
const context = await browser.newContext();
const page = await context.newPage();

// Trace every request/response so we can see the EXACT sequence around the
// "Leave" click -- status codes, URLs, and Set-Cookie headers.
page.on("request", (req) => {
  log("→", req.method(), req.url());
});
page.on("response", async (res) => {
  const setCookie = res.headers()["set-cookie"];
  log("←", res.status(), res.url(), setCookie ? `SET-COOKIE: ${setCookie}` : "");
});
page.on("console", (msg) => log("[console]", msg.type(), msg.text()));
page.on("pageerror", (err) => log("[pageerror]", err.message));

// --- 1. Admin logs in for real ---
await page.goto(`${BASE_ADMIN}/admin/login`);
await page.fill('input[name="email"]', "admin@fiximp.local");
await page.fill('input[name="password"]', "TestPass123!");
await Promise.all([
  page.waitForURL(/\/admin/, { timeout: 15000 }),
  page.click('button[type="submit"]'),
]);
log("ADMIN LOGIN DONE, url=", page.url());

// --- 2. Navigate to the test customer's admin detail page and impersonate ---
const usersRes = await page.goto(`${BASE_ADMIN}/admin/users`);
log("ADMIN USERS PAGE status=", usersRes.status());

// Find the customer row link.
const customerLink = page.locator('a[href*="/admin/users/"]').first();
const href = await customerLink.getAttribute("href");
log("customer detail href=", href);
await page.goto(`${BASE_ADMIN}${href}`);
log("CUSTOMER DETAIL url=", page.url());

// Read the BEFORE state of the Location/Sign-in IPs panel.
const beforeLocation = await page.locator("text=Location").locator("..").innerText().catch(() => "n/a");
log("BEFORE impersonation, Location panel text:", beforeLocation);

// Click Impersonate.
const impersonateForm = page.locator('form:has(button:has-text("Impersonate"))').first();
if (await impersonateForm.count() === 0) {
  log("!! No impersonate form/button found on the page. Dumping buttons:");
  const buttons = await page.locator("button").allInnerTexts();
  log(JSON.stringify(buttons));
} else {
  await Promise.all([
    page.waitForURL(/\/dashboard/, { timeout: 15000 }),
    impersonateForm.locator("button").click(),
  ]);
}
log("AFTER IMPERSONATE CLICK, url=", page.url());
log("cookies:", JSON.stringify(await context.cookies()));

// --- 3. While impersonating, reply to the customer's own ticket via the
// customer-facing support UI ---
const ticketUrl = `${BASE_ADMIN}/dashboard/support/fiximp-test-ticket`;
await page.goto(ticketUrl);
log("TICKET PAGE (impersonating) url=", page.url());
const bodyBox = page.locator('textarea[name="body"], textarea').first();
if (await bodyBox.count() > 0) {
  await bodyBox.fill("This is a reply sent while impersonating (bug 2 repro).");
  const sendBtn = page.locator('button[type="submit"]:has-text("Send"), button[type="submit"]').first();
  await sendBtn.click();
  await page.waitForTimeout(1500);
  log("Reply sent while impersonating.");
} else {
  log("!! No reply textarea found on ticket page.");
}

// --- 4. Click "Leave" to stop impersonating -- this is the bug 3 repro ---
log("=== ABOUT TO CLICK LEAVE ===");
const leaveForm = page.locator('form:has(button:has-text("Leave"))').first();
if (await leaveForm.count() === 0) {
  log("!! No Leave button found. Dumping page text.");
  log(await page.locator("body").innerText());
} else {
  const leaveBtn = leaveForm.locator("button");
  await leaveBtn.click();
  await page.waitForTimeout(3000);
}
log("=== AFTER LEAVE ===");
log("final url:", page.url());
log("final page text (first 500 chars):", (await page.locator("body").innerText()).slice(0, 500));
log("cookies after leave:", JSON.stringify(await context.cookies()));

await browser.close();

