import https from "node:https";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const TARGET_PORT = 3099; // the real Next.js standalone server
const LISTEN_PORT = 3444; // TLS-terminating front door

const options = {
  key: fs.readFileSync(path.join(__dirname, "key.pem")),
  cert: fs.readFileSync(path.join(__dirname, "cert.pem")),
};

const server = https.createServer(options, (clientReq, clientRes) => {
  const proxyReq = http.request(
    {
      hostname: "127.0.0.1",
      port: TARGET_PORT,
      path: clientReq.url,
      method: clientReq.method,
      headers: { ...clientReq.headers, "x-forwarded-proto": "https" },
    },
    (proxyRes) => {
      clientRes.writeHead(proxyRes.statusCode, proxyRes.headers);
      proxyRes.pipe(clientRes);
    },
  );
  proxyReq.on("error", (e) => {
    clientRes.writeHead(502);
    clientRes.end(`Bad gateway: ${e.message}`);
  });
  clientReq.pipe(proxyReq);
});

server.listen(LISTEN_PORT, () => {
  console.log(`TLS proxy listening on https://0.0.0.0:${LISTEN_PORT} -> http://127.0.0.1:${TARGET_PORT}`);
});

